import {createStorage} from './storage.js';
import {mountProgress,updateProgress} from './progress.js';
import {fields,bodyFields,legacyFields,folds,delta,days,validRecord,estimateBF,prepareRecord} from './calculations.js';
const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n),date=d=>d.split('-').reverse().join('/'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
mountProgress();
let records=[],demo=false,editing=null;
function message(text){$('#notice').hidden=false;$('#notice').textContent=text;if(demo){let button=document.createElement('button');button.textContent='Sair do exemplo';button.onclick=()=>{demo=false;records=real;$('#notice').hidden=true;render()};$('#notice').append(button)}}
async function persist(next){try{records=await storage.save(next);return true}catch(error){message(error.message);$('#form-error').textContent=error.message;return false}}
const signed=n=>(n>0?'+':'')+fmt(n);const val=(r,k)=>r&&Number.isFinite(r[k])?fmt(r[k])+' '+fields[k][1]:'—';
const inputMarkup=entries=>Object.entries(entries).map(([k,[name,unit]])=>`<label>${name} (${unit})<input name="${k}" type="text" inputmode="decimal" placeholder="${k==='height'?'Ex.: 175':k==='weight'?'Ex.: 75,5':unit==='mm'?'Ex.: 12,5':'Ex.: 30'}" autocomplete="off"></label>`).join('');
const measureGroups=[['Dados gerais',['weight','height']],['Tronco',['neck','shoulders','chest','waist','abdomen','hip']],['Braços · direito e esquerdo',['armRelaxedRight','armRelaxedLeft','armFlexedRight','armFlexedLeft','forearmRight','forearmLeft']],['Pernas · direita e esquerda',['thighRight','thighLeft','calfRight','calfLeft']]];
$('#inputs').innerHTML=measureGroups.map(([title,keys])=>`<h3 class="field-group">${title}</h3>${inputMarkup(Object.fromEntries(keys.map(k=>[k,bodyFields[k]])))}`).join('');
$('#legacy-inputs').innerHTML=inputMarkup(legacyFields);
$('#fold-inputs').innerHTML=inputMarkup(folds);
function readForm(){let f=$('#form'),r={id:editing||crypto.randomUUID(),date:f.elements.date.value,notes:f.elements.notes.value.trim(),sex:f.elements.sex.value,age:f.elements.age.value?Number(f.elements.age.value):null};for(let k of Object.keys(fields)){let raw=f.elements[k].value.trim();if(raw&&!/^\d+(?:[.,]\d+)?$/.test(raw))throw Error('Use números positivos, com vírgula ou ponto decimal.');r[k]=raw?Number(raw.replace(',','.')):null;}return r}
function liveBF(){try{const r=readForm(),result=estimateBF(r),hasFolds=Object.keys(folds).some(k=>r[k]!=null);$('#manual-fat').hidden=hasFolds;$('#bf-result').textContent=result.status==='ok'?fmt(result.fat)+'% de BF estimado · soma das dobras: '+fmt(result.sum)+' mm':result.message;}catch(err){$('#bf-result').textContent=err.message}}
$('#form').addEventListener('input',liveBF);
$('#metric').innerHTML=Object.entries(fields).map(([k,[n]])=>`<option value="${k}">${n}</option>`).join('');
function render(){records.sort((a,b)=>a.date.localeCompare(b.date));$('#welcome').hidden=records.length>0;let options=records.map(r=>`<option value="${esc(r.id)}">${date(r.date)}</option>`).join('');for(const s of ['#from','#to']){const old=$(s).value;$(s).innerHTML=options||'<option value="">Sem avaliações</option>';if(records.some(r=>r.id===old))$(s).value=old;}if(!$('#to').value||$('#from').value===$('#to').value)$('#to').value=records.at(-1)?.id||'';$('#records').innerHTML=records.length?records.map(r=>`<div class="record"><div><strong>${date(r.date)}</strong><p>${Object.keys(fields).filter(k=>r[k]!=null).map(k=>fields[k][0]+': '+val(r,k)).join(' · ')}</p>${r.bfMethod==='jp7-siri-v1'?`<p>BF estimado · Jackson–Pollock 7 dobras + Siri · ${r.age} anos · equação ${r.sex==='male'?'masculina':'feminina'}</p>`:r.fat!=null?'<p>BF informado manualmente · método não registrado</p>':''}${r.notes?`<small>${esc(r.notes)}</small>`:''}</div><div><button class="quiet" data-edit="${esc(r.id)}">Editar</button><button class="quiet" data-delete="${esc(r.id)}">Excluir</button></div></div>`).join(''):'<p class="empty">Sua história começa com a primeira avaliação.</p>';compare();chart();}
function bfSummary(r){if(!r)return 'Selecione uma avaliação.';const result=estimateBF(r);if(result.status!=='ok')return r.fat!=null?'BF informado manualmente: '+fmt(r.fat)+'%. Método não registrado.':result.message;return 'BF estimado: '+fmt(result.fat)+'% · Soma: '+fmt(result.sum)+' mm · Jackson–Pollock 7 dobras + Siri · Idade: '+r.age+' anos'+(r.weight!=null?' · Massa de gordura estimada: '+fmt(r.weight*result.fat/100)+' kg · Massa livre de gordura estimada: '+fmt(r.weight*(1-result.fat/100))+' kg':'')+'. Massa livre de gordura inclui água, ossos e órgãos; não equivale à massa muscular.'}
function compare(){let a=records.find(r=>r.id===$('#from').value),b=records.find(r=>r.id===$('#to').value);updateProgress(a,b);$('#composition-result').textContent=bfSummary(b);$('#bf-comparison-note').textContent=a&&b&&a.fat!=null&&b.fat!=null&&((a.bfMethod||'reported')!==(b.bfMethod||'reported')||a.sex!==b.sex)?'Atenção: BF obtido por métodos ou equações diferentes. A diferença não representa apenas mudança corporal.':'';const ordered=a&&b&&a.date<=b.date;$('#period-label').textContent=ordered?`${date(a.date)} → ${date(b.date)} · ${days(a.date,b.date)} dias entre avaliações`:'Selecione a avaliação inicial antes da final.';$('#cards').innerHTML=['weight','waist','height','fat'].map(k=>{let d=ordered?delta(a?.[k],b?.[k]):null;return `<article class="card"><div class="name">${fields[k][0]}</div><div class="value">${b?.[k]!=null?fmt(b[k]):'—'} <small>${fields[k][1]}</small></div><div class="change">${d? signed(d.absolute)+' '+(k==='fat'?'p.p.':fields[k][1])+' no período':'Aguardando medidas comparáveis'}</div></article>`}).join('');$('#compare').innerHTML=Object.keys(fields).filter(k=>!(k in legacyFields)||a?.[k]!=null||b?.[k]!=null).map(k=>{let d=ordered?delta(a?.[k],b?.[k]):null;return `<tr><td>${fields[k][0]}</td><td>${val(a,k)}</td><td>${val(b,k)}</td><td>${d?signed(d.absolute)+' '+(k==='fat'?'p.p.':fields[k][1]):'—'}</td><td>${d?.relative!=null?signed(d.relative)+'%':'—'}</td></tr>`}).join('');$('#insight').textContent=ordered&&a.id!==b.id?`Você está comparando ${days(a.date,b.date)} dias de projeto. Aumentos e reduções são exibidos sem classificação automática de “bom” ou “ruim”: o significado depende do seu objetivo.`:'Cadastre duas avaliações e selecione o período para acompanhar suas mudanças.';}
function chart(){let k=$('#metric').value,rs=records.filter(r=>Number.isFinite(r[k]));if(!rs.length){$('#chart').innerHTML='<p class="empty">Seu gráfico aparece aqui ao registrar esta medida.</p>';return}let lo=Math.min(...rs.map(r=>r[k])),hi=Math.max(...rs.map(r=>r[k])),pad=Math.max((hi-lo)*.2,1);lo-=pad;hi+=pad;const span=days(rs[0].date,rs.at(-1).date),x=r=>span?54+days(rs[0].date,r.date)/span*470:289,y=r=>180-(r[k]-lo)/(hi-lo)*150;let pts=rs.map(r=>`${x(r)},${y(r)}`).join(' ');$('#chart').innerHTML=`<svg viewBox="0 0 570 225" role="img" aria-label="Evolução de ${fields[k][0]}">${[0,1,2,3].map(i=>`<line x1="54" y1="${30+i*50}" x2="524" y2="${30+i*50}" stroke="#e9ede4" stroke-dasharray="4 4"/><text x="2" y="${34+i*50}">${fmt(hi-i*(hi-lo)/3)}</text>`).join('')}<polygon points="${x(rs[0])},180 ${pts} ${x(rs.at(-1))},180" fill="#dceacb" opacity=".5"/><polyline points="${pts}" stroke="#597643" stroke-width="2.5" fill="none"/>${rs.map(r=>`<circle tabindex="0" cx="${x(r)}" cy="${y(r)}" r="5" fill="#426138" stroke="white" stroke-width="2" aria-label="${date(r.date)}: ${val(r,k)}"><title>${date(r.date)}: ${val(r,k)}</title></circle>`).join('')}<text x="54" y="210">${date(rs[0].date)}</text>${rs.length>1?`<text x="524" y="210" text-anchor="end">${date(rs.at(-1).date)}</text>`:''}</svg>`;}
function openForm(id){if(demo){message('Saia do exemplo para cadastrar suas medidas.');return}editing=id||null;$('#form').reset();$('#form-error').textContent='';$('#dialog-title').textContent=id?'Editar avaliação':'Nova avaliação';let r=records.find(r=>r.id===id);$('#form').elements.date.value=r?.date||new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);for(let k of Object.keys(fields))$('#form').elements[k].value=r?.[k]!=null?String(r[k]).replace('.',','):'';if(r?.bfMethod==='jp7-siri-v1')$('#form').elements.fat.value='';$('#form').elements.notes.value=r?.notes||'';$('#legacy-measures').hidden=!Object.keys(legacyFields).some(k=>r?.[k]!=null);$('#form').elements.age.value=r?.age??'';$('#form').elements.sex.value=r?.sex??'';liveBF();$('#dialog').showModal()}
$('#add').onclick=()=>openForm();$('#start').onclick=()=>openForm();$('#close').onclick=()=>$('#dialog').close();$('#from').onchange=compare;$('#to').onchange=compare;$('#metric').onchange=chart;
$('#form').onsubmit=async e=>{e.preventDefault();try{let raw=readForm(),result=estimateBF(raw);if(result.status==='invalid')throw Error(result.message);let r=prepareRecord(raw);if(!validRecord(r))throw Error('Confira a data, as medidas positivas e a idade em anos completos (1 a 120). BF manual deve estar entre 0 e 100%.');if(records.some(a=>a.date===r.date&&a.id!==r.id))throw Error('Já existe uma avaliação nesta data. Edite o registro existente.');if(!await persist([...records.filter(a=>a.id!==r.id),r]))return;$('#dialog').close();$('#to').innerHTML='';render();}catch(err){$('#form-error').textContent=err.message}};
$('#records').onclick=async e=>{let edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit)openForm(edit.dataset.edit);if(del){if(demo)return message('Os registros de exemplo não podem ser alterados. Saia do exemplo para começar.');if(confirm('Excluir esta avaliação? Esta ação não pode ser desfeita.')){if(await persist(records.filter(r=>r.id!==del.dataset.delete)))render();}}};
function download(){if(demo)return message('Saia do exemplo para exportar seus dados reais.');let blob=new Blob([JSON.stringify({version:1,records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='forma-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#export').onclick=download;
$('#import').onclick=()=>{if(demo)return message('Saia do exemplo antes de importar.');$('#file').click()};$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Arquivo muito grande. Limite: 2 MB.');let data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.records)||!data.records.every(validRecord))throw Error('Este arquivo não é um backup válido do Forma.');if(new Set(data.records.map(r=>r.id)).size!==data.records.length||new Set(data.records.map(r=>r.date)).size!==data.records.length)throw Error('O backup contém registros duplicados.');if(records.length&&!confirm('Substituir as avaliações atuais pelo backup? Exporte as atuais antes, se quiser preservá-las.'))return;if(await persist(data.records.map(prepareRecord))){render();message('Backup importado com sucesso.')}}catch(err){message(err.message||'Não foi possível importar o arquivo.')}finally{e.target.value=''}};
let real=[];$('#demo').onclick=()=>{real=records;demo=true;records=[{id:'demo1',date:'2026-08-01',weight:78.4,waist:86,chest:98,arm:33,hip:100,thigh:56,calf:37,age:28,sex:'male',sfChest:15,sfAxillary:16,sfTriceps:18,sfSubscapular:20,sfAbdomen:28,sfSuprailiac:24,sfThigh:22,fat:null,notes:'Dados fictícios para demonstrar a ferramenta.'},{id:'demo2',date:'2026-09-01',weight:79.1,waist:84.5,chest:99.2,arm:33.8,hip:100,thigh:56.6,calf:37.3,age:28,sex:'male',sfChest:14,sfAxillary:15,sfTriceps:16,sfSubscapular:19,sfAbdomen:24,sfSuprailiac:21,sfThigh:20,fat:null,notes:'Dados fictícios para demonstrar a ferramenta.'}].map(prepareRecord);render();$('#notice').hidden=false;$('#notice').innerHTML='Modo de exemplo · Dados fictícios, não salvos. <button id="exit-demo">Sair do exemplo</button>';$('#exit-demo').onclick=()=>{demo=false;records=real;$('#notice').hidden=true;render()}};
const storage=createStorage({onLoad:loaded=>{demo=false;records=loaded;$('#notice').hidden=true;$('#from').innerHTML='';$('#to').innerHTML='';render()},onClear:()=>{demo=false;records=[];$('#dialog').close();$('#form').reset();$('#notice').hidden=true;render()},onMessage:message});
const navLinks=[...document.querySelectorAll('aside nav a')];
const sectionObserver=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(!visible.length)return;const id=visible[0].target.id;navLinks.forEach(link=>{const active=link.hash==='#'+id;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});},{rootMargin:'-5% 0px -65% 0px',threshold:0});
navLinks.forEach(link=>{const target=document.querySelector(link.hash);if(target&&link.hash!=='#overview')sectionObserver.observe(target);});
window.addEventListener('scroll',()=>{if(window.scrollY<180){navLinks.forEach((link,index)=>{link.classList.toggle('active',index===0);if(index===0)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}},{passive:true});
render();
await storage.boot();
